function surfaceTexture(kind){const c=document.createElement('canvas');c.width=c.height=256;const cx=c.getContext('2d');const data=cx.getImageData(0,0,256,256);const base=kind==='wood'?[174,144,98]:kind==='cardboard'?[184,148,102]:[176,188,194];for(let y=0;y<256;y++)for(let x=0;x<256;x++){const n=Math.sin(x*12.9898+y*78.233)*43758.5453;const noise=(n-Math.floor(n)-.5);const grain=kind==='wood'?Math.sin(x*.17+Math.sin(y*.018)*2)*11+noise*9:kind==='cardboard'?noise*18+Math.sin(y*3.14)*2:noise*6+Math.sin(x*.62)*4;const i=(y*256+x)*4;data.data[i]=base[0]+grain;data.data[i+1]=base[1]+grain;data.data[i+2]=base[2]+grain;data.data[i+3]=255}cx.putImageData(data,0,0);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;t.wrapS=t.wrapT=THREE.RepeatWrapping;t.userData.sharedSurface=true;return t}
