function roundedBox(g,w,h,d,m,x=0,y=0,z=0,r=.09){r=Math.min(r,w*.2,h*.2,d*.2);const a=w/2-r,b=h/2-r;const shape=new THREE.Shape();shape.moveTo(-a,-h/2);shape.lineTo(a,-h/2);shape.quadraticCurveTo(w/2,-h/2,w/2,-b);shape.lineTo(w/2,b);shape.quadraticCurveTo(w/2,h/2,a,h/2);shape.lineTo(-a,h/2);shape.quadraticCurveTo(-w/2,h/2,-w/2,b);shape.lineTo(-w/2,-b);shape.quadraticCurveTo(-w/2,-h/2,-a,-h/2);const geo=new THREE.ExtrudeGeometry(shape,{depth:d-r*2,bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:r*.4,bevelThickness:r,curveSegments:4});geo.translate(0,0,-d/2+r);geo.userData.batchKey=`rounded:${w}:${h}:${d}:${r}`;const mesh=new THREE.Mesh(geo,m);mesh.position.set(x,y,z);mesh.castShadow=true;mesh.receiveShadow=true;g.add(mesh);return mesh}
