function batchVisualMeshes(root){root.updateMatrixWorld(true);const inverse=root.matrixWorld.clone().invert(),groups=new Map();function collect(node){if(node!==root&&node.userData.visualDynamic)return;if(node.type==='Mesh'&&node.geometry.userData.batchKey&&!node.material.transparent){const key=node.material.uuid+'|'+node.geometry.userData.batchKey;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(node)}for(const child of node.children)collect(child)}collect(root);for(const list of groups.values()){if(list.length<4)continue;const first=list[0],batch=new THREE.InstancedMesh(first.geometry,first.material,list.length);batch.castShadow=first.castShadow;batch.receiveShadow=first.receiveShadow;for(let i=0;i<list.length;i++){batch.setMatrixAt(i,inverse.clone().multiply(list[i].matrixWorld));list[i].removeFromParent();if(i>0)list[i].geometry.dispose()}batch.computeBoundingSphere();root.add(batch)}}

