function setPallet(){if(activePallet){activePallet.removeFromParent();disposeGroup(activePallet)}const m=mission();activePallet=pallet(m.qty,m.sku);activePallet.position.set(m.source[0],m.source[2],m.source[1]);world.add(activePallet);deposited=false;carrying=false}
function disposeGroup(g){g.traverse(o=>{if(o.isMesh){o.geometry?.dispose();if(o.material?.map&&!o.material.map.userData.sharedSurface){o.material.map.dispose();o.material.dispose()}}})}
function makeVehicle(){if(vehicle){scene.remove(vehicle);disposeGroup(vehicle)}vehicle=mission().vehicle==='jack'?jack():forklift();vehicle.position.set(0,0,16);vehicle.rotation.y=.1;forks=vehicle.userData.forks;scene.add(vehicle);lift=.1;speed=0}
function taskTarget(){const m=mission();if(level===2)return new THREE.Vector3(...[m.source[0],0,m.source[1]]);const a=step<2?m.source:m.dest;return new THREE.Vector3(a[0],0,a[1])}
function nearTarget(){return vehicle.position.distanceTo(taskTarget())<2.85}
function routeToTarget(){for(const child of [...routeGroup.children]){child.geometry.dispose();child.material.dispose();routeGroup.remove(child)}if(!showRoute||step>=mission().steps.length)return;const target=taskTarget(),start=vehicle.position;const blocked=(x,z)=>solids.some(s=>Math.abs(x-s.x)<s.w/2+.95&&Math.abs(z-s.z)<s.d/2+.95);const startNode=[Math.round(start.x),Math.round(start.z)],end=[Math.round(target.x),Math.round(target.z)];const queue=[startNode],came=new Map([[startNode.join(','),null]]);let found;for(let i=0;i<queue.length&&i<8000;i++){const n=queue[i];if(Math.hypot(n[0]-end[0],n[1]-end[1])<2.5){found=n;break}for(const [dx,dz]of [[0,1],[1,0],[0,-1],[-1,0]]){const k=[n[0]+dx,n[1]+dz],id=k.join(',');if(k[0]<Math.ceil(HALL.minX)||k[0]>Math.floor(HALL.maxX)||k[1]<Math.ceil(HALL.minZ)||k[1]>Math.floor(HALL.maxZ)||came.has(id)||blocked(...k))continue;came.set(id,n);queue.push(k)}}if(!found)return;let path=[];for(let n=found;n;n=came.get(n.join(',')))path.push(n);path.reverse();for(let i=2;i<path.length;i+=3){const dot=new THREE.Mesh(new THREE.CircleGeometry(.16,10),new THREE.MeshBasicMaterial({color:'#f6c46b',transparent:true,opacity:.7}));dot.rotation.x=-Math.PI/2;dot.position.set(path[i][0],.04,path[i][1]);routeGroup.add(dot)}}
function renderUI(){const m=mission();$('levels').innerHTML=LEVELS.map((v,i)=>`<button class="level ${i===level?'active':''}" data-level="${i}" aria-pressed="${i===level}"><span class="level-num">${i+1}</span><span><b>${v.name}</b><small>${v.sub}</small></span>${completed.has(i)?'<span class="check">✓</span>':''}</button>`).join('');$('levels').querySelectorAll('button').forEach(b=>b.onclick=()=>chooseLevel(+b.dataset.level));$('levelCount').textContent=`${level+1} / 5`;$('vehicleLabel').textContent=m.vehicle==='jack'?'Handpompwagen':'Heftruck';$('missionTitle').textContent=m.title;$('missionDescription').textContent=m.desc;$('lessonNote').textContent=m.note;$('points').textContent=points;$('counterEntry').hidden=completed.size<5;let labels=m.steps;if(level===4&&phase===0)labels=labels.slice(0,5);$('steps').innerHTML=labels.map((s,i)=>`<li class="${i<step?'done':i===step?'current':''}"><span class="step-dot">${i<step?'✓':i+1}</span>${s}</li>`).join('');$('sceneLabel').textContent=level===2?'Magazijn · voorraad':step<2?'Magazijn · ophalen':'Magazijn · afleveren';const instructions=instruction();$('stepNumber').textContent=step+1;$('currentHint').textContent=instructions.short;$('instructionTitle').textContent=instructions.title;$('instructionText').textContent=instructions.tip;$('actionBtn').innerHTML=`${instructions.action}<span>${instructions.key||'E'}</span>`;$('actionBtn').disabled=step>=labels.length;$('height').textContent=lift.toFixed(2).replace('.',',');$('loadStatus').textContent=carrying?`${m.qty} dozen · ${m.weight} kg`:'Geen lading';document.querySelectorAll('[data-lift]').forEach(b=>b.disabled=level===2);const target=taskTarget();ring.position.copy(target);ring.position.y=.035;ghost.position.set(target.x,(step<2?m.source[2]:m.dest[2])+.1,target.z);ghost.visible=level!==2&&step===2;routeToTarget();updateCoach();updateSpeedChoice()}

