function trafficCount(){return level===0?0:level<3?1:2}
function stepPraise(){if(level===2)return ['Goed gereden! Je bent bij het juiste vak.','Goed gecontroleerd! Je koos vak B-01.','Goed geteld! Je telde alle lagen mee.','Goed gewerkt! De voorraad klopt weer.'][Math.min(step,3)];return ['Goed gedaan! Je hebt de pallet opgehaald.','Goed gecontroleerd! Dit is het juiste artikel.','Netjes! De pallet staat op de juiste plek.','Goed gescand! Je koos de juiste locatie.','Goed gewerkt! Je bon klopt.'][Math.min(step,4)]}
function coachState(){const m=mission(),distance=vehicle.position.distanceTo(taskTarget()),moving=Math.abs(speed)>.12;
 if(step>=(level===2?4:5))return {text:'Klaar! Bespreek je werkbon met je docent.',control:null};
 if(level!==2&&(step===1||step===3))return moving?{text:'Laat ↑ los. Druk op Rem. Scan pas als je stilstaat.',control:'brake'}:{text:step===1?`Klik op Scan pallet. Zoek artikelcode ${m.sku}.`:`Klik op Scan locatie. Zoek ${m.to}.`,control:'action'};
 if(level!==2&&step===4)return {text:`Klik op Papierwerk. Vul ${m.qty} dozen in. Controleer daarna schade en status.`,control:'action'};
 if(level===2&&step>0)return {text:step===1?'Klik op Scan locatie. Zoek code B-01.':step===2?'Tel eerst de onderste laag. Tel daarna de bovenste laag. Klik op Aantal invoeren.':'Je telde 6 dozen. De computer zegt 8. Klik op Voorraad bijwerken.',control:'action'};
 if(carrying&&distance>2.85&&lift>(m.vehicle==='jack'?.27:.55))return {text:'Eerst de lading laag: houd Omlaag ingedrukt. Rijd daarna verder.',control:'down'};
 if(distance>2.85&&people.slice(0,peopleCount()).some(p=>vehicle.position.distanceTo(p.mesh.position)<2.65))return {text:'Een voetganger loopt dichtbij. Druk op Rem. Wacht tot het pad vrij is.',control:'brake'};if(distance>2.85&&traffic.slice(0,trafficCount()).some(t=>vehicle.position.distanceTo(t.mesh.position)<3.2))return {text:'Een heftruck komt langs. Druk op Rem. Houd afstand en wacht.',control:'brake'};if(distance>2.85){const waypoint=routeGroup.children[0]?.position||taskTarget(),dx=waypoint.x-vehicle.position.x,dz=waypoint.z-vehicle.position.z;let angle=Math.atan2(-dx,-dz)-vehicle.rotation.y;angle=Math.atan2(Math.sin(angle),Math.cos(angle));if(Math.abs(angle)>.4)return {text:`Volg de gele stippen. Houd ↑ en ${angle>0?'←':'→'} kort tegelijk ingedrukt. Laat los om te stoppen.`,control:angle>0?'left':'right'};return {text:'Je rijdt de goede kant op. Houd ↑ rustig ingedrukt. Stop bij de groene ring.',control:'forward'}}
 if(moving)return {text:'Je bent dichtbij. Laat ↑ los. Druk op Rem.',control:'brake'};
 if(level===2)return {text:'Je bent bij vak B-01. Klik op Ik ben er.',control:'action'};
 const target=taskTarget(),forward=new THREE.Vector3(0,0,-1).applyAxisAngle(new THREE.Vector3(0,1,0),vehicle.rotation.y),delta=target.clone().sub(vehicle.position).normalize();
 if(distance>1&&forward.dot(delta)<.25)return {text:'Je staat dichtbij. Richt je vorken op de pallet. Klik op Help mij voor hulp met richten.',control:'help'};
 const h=step===0?m.source[2]:m.dest[2];if(Math.abs(lift-h)>.23)return {text:`Houd ${lift<h?'Omhoog':'Omlaag'} ingedrukt tot ${h.toFixed(2).replace('.',',')} m. Of gebruik de hoogtehulp bij Help mij.`,control:lift<h?'up':'down'};
 return {text:step===0?'Je staat goed! Klik op Pak pallet.':'De plek en hoogte kloppen! Klik op Zet pallet neer.',control:'action'};
}
