function brief(start=false){const m=mission();openModal(`<div class="eyebrow orange">OPDRACHTBRIEF · NIVEAU ${level+1}${phase?' · DEEL 2':''}</div><h2>${m.title}</h2><p>${m.desc}</p><div class="brief"><div class="brief-row"><span>Artikel</span><b>${m.article}</b></div><div class="brief-row"><span>Artikelcode</span><b>${m.sku}</b></div><div class="brief-row"><span>${level===2?'Computervoorraad':'Aantal'}</span><b>${level===2?m.registered:m.qty} dozen</b></div><div class="brief-row"><span>Ophalen</span><b>${m.from}</b></div><div class="brief-row"><span>${level===2?'Controleer':'Afleveren'}</span><b>${m.to}</b></div></div>${start?'<div class="lesson-tip"><b>Eerst één ding:</b> volg de gele stippen naar de groene ring. Gebruik ↑ om te rijden. Stuur met ← en →. De hulpstrook vertelt je onderweg wat je moet doen.</div>':''}<p>${m.note}</p><div class="modal-actions"><button class="primary" id="startMission">${start?'Start opdracht':'Verder oefenen'} →</button></div>`);$('startMission').onclick=closeModal}
function action(){if(modalOpen||paused)return;if(level===2){if(step===0){if(!nearTarget())return toast('Rijd eerst naar de groene ring bij B-01.',true);nextStep()}else if(step===1)scan();else if(step===2)countDialog();else inventoryDialog();return}if(step===1||step===3)return scan();if(step===4)return paperDialog();if(!nearTarget())return toast('Je staat nog te ver weg. Rijd naar de groene ring.',true);if(Math.abs(speed)>.12)return toast('Stop eerst. Pak of plaats een pallet alleen als je stilstaat.',true);const m=mission(),target=taskTarget();const forward=new THREE.Vector3(0,0,-1).applyAxisAngle(new THREE.Vector3(0,1,0),vehicle.rotation.y);const delta=target.clone().sub(vehicle.position).normalize();if(vehicle.position.distanceTo(target)>1&&forward.dot(delta)<.25)return toast('Richt de voorkant en de vorken op de pallet.',true);const h=step===0?m.source[2]:m.dest[2];if(Math.abs(lift-h)>.23)return toast(`Zet de vorken op ${h.toFixed(2).replace('.',',')} m. Gebruik Omhoog of Omlaag.`,true);if(step===0){carrying=true;activePallet.removeFromParent();forks.add(activePallet);activePallet.position.set(0,.13, m.vehicle==='jack'?-.45:-1.77);history.push({actie:'Pallet opgehaald',artikel:m.sku,locatie:m.from});nextStep()}else if(step===2){carrying=false;deposited=true;activePallet.removeFromParent();world.add(activePallet);activePallet.position.set(m.dest[0],m.dest[2],m.dest[1]);history.push({actie:'Pallet geplaatst',artikel:m.sku,locatie:m.to});nextStep()}}
function scan(){if(modalOpen||paused)return;if(Math.abs(speed)>.12)return toast('Stop voordat je scant.',true);const m=mission();if(level===2&&step!==1)return toast('Je scant tijdens de stap ‘Locatie scannen’.',true);if(level!==2&&step!==1&&step!==3)return toast('Pak eerst de pallet, of plaats hem voordat je de locatie scant.',true);if((step===3||level===2)&&!nearTarget())return toast('Rijd eerst naar de juiste locatie. Je scanner heeft een kort bereik.',true);const article=level!==2&&step===1,expected=article?m.sku:m.to;const location=level===2?'B-01':m.to;const choices=article?[m.sku,'XX-999','SM-300'].filter((v,i,a)=>a.indexOf(v)===i):[location,location==='A-01'?'A-02':'A-01','Verzending · dock 1'];openModal(`<div class="eyebrow orange">HANDSCANNER</div><h2>${article?'Scan de pallet':'Scan de locatie'}</h2><p>Je opdracht vraagt om <b>${expected}</b>. Vergelijk de code met het etiket.</p><div class="scan-visual"><div class="barcode"></div><b>${expected}</b><p style="margin-bottom:0;font-size:14px">${article?m.article:'Locatie-etiket bij jouw bestemming'}</p></div><label class="form-field"><span>Welke code staat op het etiket?</span><select id="scanChoice"><option value="">Kies de juiste code</option>${choices.sort(()=>Math.random()-.5).map(v=>`<option>${v}</option>`).join('')}</select></label><p id="scanError" class="form-error" role="alert"></p><div class="modal-actions"><button id="scanCancel">Terug</button><button class="primary" id="confirmScan">Bevestig scan</button></div>`);$('scanCancel').onclick=closeModal;$('confirmScan').onclick=()=>{if($('confirmScan').disabled)return;if($('scanChoice').value!==expected){$('scanError').textContent=`Bijna! Zoek ${expected} in de lijst. Die code staat ook op het etiket.`;errors++;return}$('confirmScan').disabled=true;history.push({actie:article?'Artikel gescand':'Locatie gescand',artikel:m.sku,locatie:expected});closeModal();nextStep()}}
function countDialog(){if(!nearTarget())return toast('Ga naar B-01 om de dozen te tellen.',true);openModal(`<div class="eyebrow orange">INVENTARISEREN · B-01</div><h2>Tel de dozen</h2><p>Bekijk de pallet in het magazijn. Tel alle dozen, ook de bovenste laag.</p><label class="form-field"><span>Hoeveel dozen tel je?</span><input id="countInput" type="number" min="0" max="30" inputmode="numeric" placeholder="Vul het aantal in"></label><p class="form-error" id="countError" role="alert"></p><div class="modal-actions"><button id="countBack">Nog eens kijken</button><button class="primary" id="countConfirm">Controleer telling</button></div>`);$('countBack').onclick=closeModal;$('countConfirm').onclick=()=>{if($('countConfirm').disabled)return;if($('countInput').value===''||+$('countInput').value!==mission().qty){$('countError').textContent=(++countAttempts>1?'Onder liggen 4 dozen. Boven liggen 2 dozen. Hoeveel is dat samen?':'Goed dat je controleert. Tel eerst de onderste laag. Tel daarna de bovenste laag erbij.');errors++;return}$('countConfirm').disabled=true;history.push({actie:'Voorraad geteld',aantal:mission().qty,locatie:'B-01'});closeModal();nextStep()}}
function inventoryDialog(){openModal(`<div class="eyebrow orange">VOORRAAD BIJWERKEN</div><h2>De computer klopt niet</h2><div class="brief"><div class="brief-row"><span>Computer</span><b>8 dozen</b></div><div class="brief-row"><span>Jouw telling</span><b>6 dozen</b></div></div><label class="form-field"><span>Wat doe je?</span><select id="inventoryChoice"><option value="">Kies je actie</option><option value="keep">Laat 8 dozen staan</option><option value="correct">Pas de voorraad aan naar 6 dozen en meld 2 dozen verschil</option><option value="hide">Verberg het verschil</option></select></label><p class="form-error" id="inventoryError" role="alert"></p><div class="modal-actions"><button class="primary" id="inventoryConfirm">Verwerk voorraad</button></div>`);$('inventoryConfirm').onclick=()=>{if($('inventoryConfirm').disabled)return;if($('inventoryChoice').value!=='correct'){$('inventoryError').textContent='Je telde 6 dozen. Kies de regel met 6 dozen en 2 dozen verschil. Meld het verschil bij je begeleider.';errors++;return}$('inventoryConfirm').disabled=true;history.push({actie:'Voorraad aangepast',van:8,naar:6,verschil:-2});closeModal();nextStep()}}
function paperDialog(){const m=mission(),shipping=level===3||phase===1;openModal(`<div class="eyebrow orange">${shipping?'VERZENDING':'GOEDERENONTVANGST'} · DOCUMENT ${shipping?'PK':'ON'}-00${level+1}</div><h2>${shipping?'Pakbon':'Ontvangstbon'} invullen</h2><p>Controleer de pallet. In deze opdracht zie je geen beschadigde dozen.</p><div class="brief"><div class="brief-row"><span>Artikel</span><b>${m.article} · ${m.sku}</b></div><div class="brief-row"><span>Locatie</span><b>${m.to}</b></div></div><label class="form-field"><span>Aantal dozen</span><input id="paperQty" type="number" min="0" inputmode="numeric" placeholder="Hoeveel dozen heb je verwerkt?"></label><label class="form-field"><span>Schade aan de dozen?</span><select id="paperDamage"><option value="">Kies je controle</option><option value="no">Nee, dozen zijn heel</option><option value="yes">Ja, schade melden</option></select></label><label class="form-field"><span>Wat bevestig je?</span><select id="paperStatus"><option value="">Kies de juiste status</option><option value="received">Ontvangen en opgeslagen</option><option value="shipped">Gecontroleerd en geladen voor verzending</option></select></label><p class="form-error" id="paperError" role="alert"></p><div class="modal-actions"><button id="paperBack">Terug</button><button class="primary" id="paperConfirm">Bon afronden</button></div>`);$('paperBack').onclick=closeModal;$('paperConfirm').onclick=()=>{if($('paperConfirm').disabled)return;if($('paperQty').value===''||+$('paperQty').value!==m.qty||$('paperDamage').value!=='no'||$('paperStatus').value!==(shipping?'shipped':'received')){$('paperError').textContent=$('paperQty').value===''||+$('paperQty').value!==m.qty?`Kijk op je opdracht: ${m.qty} dozen. Vul dat aantal in.`:$('paperDamage').value!=='no'?'De dozen zijn heel. Kies: Nee, dozen zijn heel.':shipping?'Je hebt de vrachtwagen geladen. Kies de status voor verzending.':'Je hebt de levering opgeslagen. Kies: Ontvangen en opgeslagen.';errors++;return}$('paperConfirm').disabled=true;history.push({actie:shipping?'Pakbon afgerond':'Ontvangstbon afgerond',aantal:m.qty,artikel:m.sku,schade:false});closeModal();nextStep()}}
function finish(){completed.add(level);renderUI();const allDone=completed.size===5;openModal(`<div class="eyebrow orange">OPDRACHT AFGEROND</div><h2>${allDone?'Alle magazijnmissies gehaald!':'Goed gewerkt!'}</h2><p>Je hebt ${level===2?'de voorraad geteld en het verschil verwerkt':'de goederen verwerkt en het papierwerk afgerond'}.</p><div class="result-grid"><div><b>${points}</b><span>totaalpunten</span></div><div><b>${errors}</b><span>keer opnieuw geprobeerd</span></div><div><b>${completed.size}/5</b><span>missies gehaald</span></div></div><div class="lesson-tip">${allDone?'De balie en winkel zijn nu open. Je punten blijven staan. Help tien klanten en rond daarna de werkdag af.':errors?'Bespreek met je docent welke stap je nog eens wilt oefenen.':'Je hebt alle controles goed uitgevoerd. Leg je docent uit waarom scannen belangrijk is.'}</div><p>${safetyStops} veiligheidsstop${safetyStops===1?'':'s'}. Kijk bij elke rit opnieuw om je heen.</p><div class="modal-actions"><button id="resultDownload">Download werkbon</button><button id="resultAgain">Nog eens</button><button class="primary" id="resultNext">${allDone?'Naar balie & winkel':level<4?'Volgend niveau':'Kies een nieuwe opdracht'} →</button></div>`);$('resultAgain').onclick=()=>{closeModal();chooseLevel(level)};$('resultNext').onclick=()=>{closeModal();allDone?window.dispatchEvent(new CustomEvent('open-retail')):chooseLevel(level<4?level+1:0)};$('resultDownload').onclick=downloadReport;window.dispatchEvent(new CustomEvent('mission-completed',{detail:{level,points,completed:completed.size}}))}
function downloadReport(){const data=['MAGAZIJN MISSIE — WERKBON',`Niveau: ${level+1} — ${LEVELS[level].name}`,`Datum: ${new Date().toLocaleDateString('nl-NL')}`,`Punten: ${points}`,`Opnieuw geprobeerd: ${errors}`,`Veiligheidsstops: ${safetyStops}`,'',...history.map(h=>Object.entries(h).map(([k,v])=>`${k}: ${v}`).join(' | ')),'','Bespreek deze werkbon met je docent. Deze simulatie geeft geen rijbevoegdheid.'].join('\n');const blob=new Blob([data],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`werkbon-magazijn-niveau-${level+1}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function help(){openModal(`<div class="eyebrow orange">ZO WERKT HET</div><h2>Je oefent een echte werkvolgorde.</h2><p>Lees de opdracht. Volg de groene bestemming. Controleer elke stap voor je verdergaat.</p><img class="reference-image" src="magazijn-praktijk.png" alt="Fotorealistische oefenbeelden: een heftruck, een rode handpompwagen en een medewerker met een scanner"><div class="help-grid"><div><b>1 · Rijden</b><p>Pijltjes: vooruit, achteruit en sturen. Spatie: rem. Laat de knop los om rustig te stoppen.</p></div><div><b>2 · Vorken</b><p>R: omhoog. F: omlaag. Een pompwagen heft maar een klein stukje. Een heftruck bereikt hoge vakken.</p></div><div><b>3 · Pallet verwerken</b><p>Stop dichtbij. Richt je vorken op de pallet. E: pakken of neerzetten. De vorkhoogte moet kloppen.</p></div><div><b>4 · Controleren</b><p>S: scan. Controleer code en locatie. Tel de dozen en vul de bon in. H: claxon.</p></div></div><div class="lesson-tip">Voetganger of voertuig dichtbij? Stop en wacht. De claxon geeft je geen voorrang. Rijd met een lage lading.</div><p style="font-size:14px">Dit spel vereenvoudigt de praktijk. De beelden hierboven zijn gegenereerde oefenbeelden. Oefen met echte voertuigen alleen volgens de afspraken van je school en onder begeleiding. Dit spel geeft geen rijbevoegdheid.</p><div class="modal-actions"><button class="primary" id="helpClose">Verder oefenen</button></div>`);$('helpClose').onclick=closeModal}
function teacher(){openModal(`<div class="eyebrow orange">VOOR DE DOCENT · PRAKTIJKONDERWIJS</div><h2>Een magazijnles in 50 minuten</h2><ul><li><b>5 min:</b> bekijk pompwagen, heftruck, stelling en scanner.</li><li><b>10 min:</b> doe niveau 1 samen voor. Laat de leerling elke stap benoemen.</li><li><b>20 min:</b> oefen in tweetallen. Eén rijdt, één leest de opdracht. Wissel daarna.</li><li><b>10 min:</b> koppel de werkvolgorde aan een echte oefenpallet en een pakbon.</li><li><b>5 min:</b> bespreek de werkbon en één verbeterpunt.</li></ul><div class="brief"><b>Wat observeer je?</b><p>Volgt de leerling de opdracht? Kiest die het juiste artikel en vak? Telt die zorgvuldig? Stopt die voor anderen? Houdt die de lading laag? Rondt die de bon af?</p></div><p>Niveau 1: langzame handpompwagen, één voetganger en geen andere heftruck. De vaste hulpstrook geeft één aanwijzing tegelijk. Help mij geeft korte deelstappen en hulp bij richten of vorkhoogte. Fouten kosten geen punten. Niveau 1: handpompwagen en begeleiding. Niveau 2: hoge opslag. Niveau 3: tellen en voorraadverschil. Niveau 4: klantorder. Niveau 5: ontvangst én verzending met meer verkeer.</p><p>De app slaat geen namen of leerlinggegevens op. De werkbon download je op dit apparaat. De simulator vereenvoudigt sturen, ladinggewicht, dockhoogte en scans.</p><div class="modal-actions"><button id="teacherDownload">Download huidige werkbon</button><button class="primary" id="teacherClose">Terug naar het spel</button></div>`);$('teacherClose').onclick=closeModal;$('teacherDownload').onclick=downloadReport}
function horn(){hornTime=1;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),gain=ctx.createGain();o.type='triangle';o.frequency.value=310;gain.gain.value=.12;o.connect(gain);gain.connect(ctx.destination);o.start();gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.25);o.stop(ctx.currentTime+.3);setTimeout(()=>ctx.close(),500)}catch{}toast('Claxon. Blijf kijken: je hebt geen voorrang.')}
function removePause(){document.querySelector('.paused-overlay')?.remove();$('pauseBtn').textContent='Ⅱ'}
function pause(){paused=!paused;keys={};speed=0;if(paused){const d=document.createElement('div');d.className='paused-overlay';d.innerHTML='<button id="resumeGame" class="primary">▶ Verder oefenen</button>';$('gameArea').append(d);$('resumeGame').onclick=pause;$('pauseBtn').textContent='▶'}else removePause()}
function speakHint(){if(!('speechSynthesis'in window))return toast('Vraag je maatje om de hint voor te lezen. Deze browser kan niet voorlezen.',true);speechSynthesis.cancel();const u=new SpeechSynthesisUtterance($('coachHint').textContent);u.lang='nl-NL';u.rate=.8;speechSynthesis.speak(u)}
function read(){if(!('speechSynthesis'in window))return toast('Voorlezen werkt niet in deze browser.',true);speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(`${mission().title}. ${mission().desc} ${instruction().title} ${instruction().tip}`);u.lang='nl-NL';u.rate=.82;speechSynthesis.speak(u)}
function bindHold(button,on,off){button.addEventListener('pointerdown',e=>{e.preventDefault();if(modalOpen||paused)return;button.setPointerCapture(e.pointerId);on()});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,off)}
for(const b of document.querySelectorAll('[data-drive]'))bindHold(b,()=>keys[b.dataset.drive]=true,()=>keys[b.dataset.drive]=false);for(const b of document.querySelectorAll('[data-lift]'))bindHold(b,()=>keys[b.dataset.lift]=true,()=>keys[b.dataset.lift]=false);
const keyMap={ArrowUp:'forward',w:'forward',ArrowDown:'backward',ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',r:'up',f:'down',' ':'brake'};
window.addEventListener('keydown',e=>{if(retailMode||modalOpen||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(k))e.preventDefault();if(paused)return;if(k==='s'&&!e.repeat)return scan();if(keyMap[k])keys[keyMap[k]]=true;if(!e.repeat){if(k==='e')action();if(k==='h')horn();if(k==='p')pause()}});window.addEventListener('keyup',e=>{const k=e.key.length===1?e.key.toLowerCase():e.key;if(keyMap[k])keys[keyMap[k]]=false});window.addEventListener('blur',()=>{keys={};speed=0});document.addEventListener('visibilitychange',()=>{keys={};speed=0});
$('speedChoice').onchange=()=>{speedMode=$('speedChoice').value;updateSpeedChoice();toast(({calm:'Rustig rijden. Neem de tijd.',normal:'Normale snelheid. Rem op tijd bij je bestemming.',quick:'Vlot rijden. Rem voor bochten, pallets en anderen.'})[speedMode])};$('coachHelp').onclick=coachHelp;$('coachRead').onclick=()=>speakHint();$('helpBtn').onclick=help;$('teacherBtn').onclick=teacher;$('assignmentBtn').onclick=()=>brief();$('resetBtn').onclick=()=>chooseLevel(level);$('actionBtn').onclick=action;$('scanBtn').onclick=scan;$('hornBtn').onclick=horn;$('pauseBtn').onclick=pause;$('readBtn').onclick=read;$('hintBtn').onclick=()=>{showRoute=!showRoute;routeToTarget();$('hintBtn').textContent=showRoute?'Route':'Route aan'};bindHold($('brakeBtn'),()=>keys.brake=true,()=>keys.brake=false);
$('counterEntry').onclick=()=>window.dispatchEvent(new CustomEvent('open-retail'));
