function moveAlong(actor,dt){actor.t+=dt*actor.speed;const [a,b]=actor.route,length=Math.hypot(b[0]-a[0],b[1]-a[1]),v=actor.t%(length*2),out=v<length,ratio=(out?v:2*length-v)/length;actor.mesh.position.set(a[0]+(b[0]-a[0])*ratio,0,a[1]+(b[1]-a[1])*ratio);actor.mesh.rotation.y=Math.atan2(-(out?b[0]-a[0]:a[0]-b[0]),-(out?b[1]-a[1]:a[1]-b[1]));if(actor.mesh.userData.legs)actor.mesh.userData.legs.forEach((l,i)=>l.rotation.x=Math.sin(actor.t*5+i*Math.PI)*.22)}
function collides(p){if(p.x<HALL.minX||p.x>HALL.maxX||p.z<HALL.minZ||p.z>HALL.maxZ)return 'Je bereikt de rand van het magazijn. Stuur terug.';for(const s of solids)if(Math.abs(p.x-s.x)<s.w/2+.85&&Math.abs(p.z-s.z)<s.d/2+.8)return 'Let op de stelling of het obstakel. Neem meer ruimte.';if(!carrying&&step!==0&&level!==2&&activePallet&&p.distanceTo(activePallet.position)<1.05)return 'De pallet staat hier. Rijd eromheen.';for(const p2 of people.slice(0,peopleCount()))if(p.distanceTo(p2.mesh.position)<2.05&&p.distanceTo(p2.mesh.position)<vehicle.position.distanceTo(p2.mesh.position)-.00001)return 'Voetganger dichtbij. Stop en wacht tot het looppad vrij is.';for(const t of traffic.slice(0,trafficCount()))if(p.distanceTo(t.mesh.position)<2.6&&p.distanceTo(t.mesh.position)<vehicle.position.distanceTo(t.mesh.position)-.00001)return 'Een andere heftruck komt langs. Houd afstand en wacht.';return null}
